@section('content')<div class="mx-auto max-w-7xl px-5 py-10 lg:px-8"><div class="mb-6 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p class="text-xs font-extrabold uppercase tracking-widest text-brand-600">LOKASI KOS</p><h1 class="mt-2 text-3xl font-black">Peta Kos</h1><p class="mt-2 text-sm text-slate-500">Pilih marker untuk melihat ringkasan kos dan membuka detail.</p></div><a href="{{ route('kos.cari') }}" class="rounded-xl bg-brand-600 px-5 py-3 text-sm font-bold text-white">Kembali ke pencarian</a></div><div id="kos-map" class="z-0 h-[560px] overflow-hidden rounded-2xl border border-emerald-100 shadow-soft"></div><p class="mt-3 text-xs text-slate-500">Peta menggunakan Leaflet dan OpenStreetMap. Jika peta gagal dimuat, daftar kos tetap dapat dibuka melalui halaman pencarian.</p></div>@endsection
@push('scripts')<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin=""></script><script>
const kosPoints = @json($kos->map(fn($k)=>['id'=>$k->id,'nama'=>$k->nama_kos,'alamat'=>$k->alamat,'jenis'=>$k->jenis_kos,'lat'=>(float)$k->latitude,'lng'=>(float)$k->longitude,'foto'=>$k->fotoKos->first()?->url_foto,'harga'=>$k->kamarKos->where('status_kamar','tersedia')->min('harga_per_bulan')])->values());
const map = L.map('kos-map').setView([-8.2192,114.3693], 13);
L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);
const markers=[]; kosPoints.forEach(k=>{const marker=L.marker([k.lat,k.lng]).addTo(map);marker.bindPopup(`<div style="min-width:190px"><b>${String(k.nama).replaceAll('<','&lt;')}</b><p style="margin:5px 0;color:#64748b;font-size:12px">${String(k.alamat).replaceAll('<','&lt;')}</p><p style="color:#168653;font-weight:700">${k.harga ? 'Rp'+Number(k.harga).toLocaleString('id-ID')+'/bulan' : 'Hubungi pemilik'}</p><a style="color:#168653;font-weight:700" href="/kos/${k.id}">Lihat detail →</a></div>`);markers.push(marker)});if(markers.length){const group=L.featureGroup(markers);map.fitBounds(group.getBounds().pad(.18))}
</script>@endpush
